    private List<String> itemTexts(ItemsView view) {
        return view.itemList.getChildren().map(child -> ((ListItem) child).getText()).toList();
    }

    @Test
    void view_is_shown_inside_the_app_shell() {
        navigate(ItemsView.class);

        assertThat($(AppLayout.class).exists()).isTrue();
        assertThat($(H2.class).first().getText()).isEqualTo("Item Tracker");
        assertThat($(H1.class).first().getText()).isEqualTo("Items");
        assertThat($(UnorderedList.class).exists()).isTrue();
    }

    @Test
    void empty_view_has_no_items() {
        var view = navigate(ItemsView.class);

        assertThat(itemTexts(view)).isEmpty();
        assertThat(view.itemCount.getText()).isEqualTo("Items: 0");
        assertThat(view.itemField.getValue()).isEmpty();
        assertThat(view.itemField.getLabel()).isEqualTo("Item");
        assertThat(view.addButton.isEnabled()).isTrue();
        assertThat(view.clearButton.isEnabled()).isTrue();
    }

    @Test
    void adding_an_item_appends_it_and_empties_the_field() {
        var view = navigate(ItemsView.class);

        test(view.itemField).setValue("Milk");
        test(view.addButton).click();

        assertThat(itemTexts(view)).containsExactly("Milk");
        assertThat(view.itemCount.getText()).isEqualTo("Items: 1");
        assertThat(view.itemField.getValue()).isEmpty();
        assertThat(view.itemField.isInvalid()).isFalse();
    }

    @Test
    void items_are_added_in_order_and_may_repeat() {
        var view = navigate(ItemsView.class);

        for (var item : List.of("Milk", "Bread", "Milk")) {
            test(view.itemField).setValue(item);
            test(view.addButton).click();
        }

        assertThat(itemTexts(view)).containsExactly("Milk", "Bread", "Milk");
        assertThat(view.itemCount.getText()).isEqualTo("Items: 3");
    }

